package com.openggf.game.soniccd;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.junit.jupiter.api.parallel.Isolated;import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;import static com.openggf.game.soniccd.objects.CdObjectState.LongField.*;
/** Java UNRUN. Actual public Boot/World/clear/store/capture producers, labelled constructed pool Seed. */
@Isolated class TestSonicCdR31aFlowerPositionWorld {
 @TempDir Path directory;final TestSonicCdR31aSelectedProfileLoading f=new TestSonicCdR31aSelectedProfileLoading();
 @BeforeEach void setup(){f.directory=directory;f.setup();}@AfterEach void cleanup(){f.cleanup();}
 @Test void genuineReachedClearKnowsExactlyTheDeclaredPositionSlice()throws Exception{try(var b=f.start(1,0x80)){TestSonicCdR31aSelectedProfileLoading.ready(b);var core=b.module.r31LoadingVisit();assertTrue(core.state().calls().contains(SonicCdR31aLoadingVisit.Call.CLEAR_FLOWERS));var p=core.state().flowerPositions();assertTrue(p.clearedByOriginal());assertEquals(768,p.knownBytes());for(int offset=0;offset<768;offset+=2)assertEquals(0,p.word(offset));assertThrows(CdFlowerPositions.Unavailable.class,()->p.word(768));}}
 @Test void publicSeedPositionStoresAndFullCourseReplayUseTheSameExistingOwners()throws Exception{try(var b=f.start(1,0x80)){TestSonicCdR31aSelectedProfileLoading.ready(b);TestSonicCdR31aSelectedProfileLoading.step(b,8);var h=b.module.r31WorldHost();var frame=b.module.requirePlayerFrame();var core=b.module.r31LoadingVisit();var pool=h.placement().pool();for(int w=32;w<128;w++)pool.deleteObject(w);pool.write(pool.state(32).moveByte(ID,0x1F).moveByte(ROUTINE,2).moveByte(SUBTYPE,0).moveByte(SPRITE_FLAGS,4).moveWord(X,96).moveWord(Y,1024).moveLong(MAPPINGS,0x2336D8).moveWord(TILE,0x6D7));var r=b.mode.getRewindRegistry();var full=r.capture();var course=r.captureCourse();TestSonicCdR31aSelectedProfileLoading.step(b,8);var expected=core.state().flowerPositions();assertEquals(96,expected.word(0x100));assertEquals(pool.state(32).centreY(),expected.word(0x102));assertEquals(4,pool.state(32).routine());for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);assertEquals(0,core.state().flowerPositions().word(0x100));TestSonicCdR31aSelectedProfileLoading.step(b,8);assertEquals(expected,core.state().flowerPositions());assertSame(frame,b.module.requirePlayerFrame());assertSame(h,b.module.r31WorldHost());assertFalse(frame.closed());}}}
}
